func _run_tests() -> void:
	var validator = instantiate_script("res://story/story_validator.gd")
	if not check("validator_esiste", validator != null, "Lo script res://story/story_validator.gd deve esistere"):
		return

	if not check("ha_find_unreachable", has_function(validator, "find_unreachable_labels"), "StoryValidator deve avere la funzione find_unreachable_labels(file_path: String) -> Array[String]"):
		return

	# 1. Rete corretta già presente: tutte le etichette devono essere raggiungibili
	var unreach_network: Array = validator.find_unreachable_labels("res://story/network_story.json")
	check("network_nessun_orfano", unreach_network.is_empty(), "In network_story.json tutte le etichette sono collegate: non deve segnalarne alcuna come irraggiungibile (segnalate: %s)" % str(unreach_network))

	var unreach_branch: Array = validator.find_unreachable_labels("res://story/branching_story.json")
	check("branch_nessun_orfano", unreach_branch.is_empty(), "In branching_story.json tutte le etichette sono collegate: la lista deve essere vuota")

	# 2. Storia con etichetta mai raggiungibile (orfana)
	var file_orphan := "user://test_orphan_label.json"
	var f1 := FileAccess.open(file_orphan, FileAccess.WRITE)
	f1.store_string(JSON.stringify({
		"lines": [
			{"type": "line", "speaker": "Elena", "text": "Inizio del cammino."},
			{"type": "jump", "target": "fine_percorso"},
			{"type": "label", "id": "vicolo_cieco"},
			{"type": "line", "speaker": "Elena", "text": "Questo punto è orfano e irraggiungibile."},
			{"type": "label", "id": "fine_percorso"},
			{"type": "line", "speaker": "Marco", "text": "Fine del cammino."}
		]
	}))
	f1.close()

	var unreach_orphan: Array = validator.find_unreachable_labels(file_orphan)
	check("trova_orfano", unreach_orphan.has("vicolo_cieco"), "Deve individuare l'etichetta 'vicolo_cieco' come mai raggiungibile (trovate: %s)" % str(unreach_orphan))
	check("non_segnala_raggiungibile", not unreach_orphan.has("fine_percorso"), "L'etichetta 'fine_percorso' è raggiunta dal jump e non deve essere segnalata")

	# 3. Storia con ciclo (loop) e controllo di non blocco
	var file_cycle := "user://test_cycle.json"
	var f2 := FileAccess.open(file_cycle, FileAccess.WRITE)
	f2.store_string(JSON.stringify({
		"lines": [
			{"type": "label", "id": "piazza"},
			{"type": "line", "speaker": "Elena", "text": "Siamo nella piazza centrale."},
			{
				"type": "choice",
				"options": [
					{"text": "Resta in piazza", "target": "piazza"},
					{"text": "Esci", "target": "uscita"}
				]
			},
			{"type": "label", "id": "uscita"},
			{"type": "line", "speaker": "Marco", "text": "Siamo usciti!"},
			{"type": "label", "id": "stanza_dimenticata"},
			{"type": "line", "speaker": "Marco", "text": "Nessuno può arrivare qui."}
		]
	}))
	f2.close()

	var unreach_cycle: Array = validator.find_unreachable_labels(file_cycle)
	check("gestisce_cicli", unreach_cycle.has("stanza_dimenticata"), "In una rete con cicli deve terminare senza bloccarsi e individuare l'etichetta 'stanza_dimenticata' come irraggiungibile")
	check("ciclo_raggiungibili_ok", not unreach_cycle.has("piazza") and not unreach_cycle.has("uscita"), "Le etichette 'piazza' e 'uscita' sono raggiungibili e non vanno segnalate")
",
   "descrizione": "find_unreachable_labels rileva i punti orfani, gestisce i bivi e termina correttamente in presenza di cicli senza bloccare l'esecuzione"
  }
